TEST_CASE("InspectorHost: pruning a source keeps the cursor on its own entry after an earlier clamp", "[editor][inspector]")
{
    World w;
    FakeSource third{ "third.arcshader" };
    w.host.AddSource(third);
    w.Select(third, "t1");
    w.Select(w.doc, "a");
    w.Select(w.other, "n1");
    w.Select(w.scene, "7");
    REQUIRE(w.host.GoBack());                       // other n1
    REQUIRE(w.host.GoBack());                       // doc a  (cursor 1, Current == doc)
    w.host.RemoveSource(w.doc);                     // cursor entry removed: clamps onto other n1, Current -> scene
    REQUIRE(w.host.History().size() == 3);
    CHECK(w.host.HistoryCursor() == 1);
    CHECK(w.host.History()[1].source == &w.other);
    w.host.RemoveSource(third);                     // an entry BEFORE the cursor goes
    REQUIRE(w.host.History().size() == 2);
    CHECK(w.host.HistoryCursor() == 0);             // unfixed code leaves 1 -> scene 7
    CHECK(w.host.History()[0].source == &w.other);
    CHECK(w.host.History()[0].key == "n1");
}
